import sys

def main():
    import sys
    import heapq

    def dijkstra(n, m, ships):
        # Initialize the DP table with infinity
        dp = [[float('inf')] * (2 * n + 1) for _ in range(n + 1)]
        dp[0][n] = 0

        # Priority queue for Dijkstra's algorithm
        pq = [(0, 0, n)]

        while pq:
            cost, t, x = heapq.heappop(pq)

            if cost > dp[t][x]:
                continue

            if t == n:
                return reconstruct_path(dp, n, x)

            for dx in [-1, 0, 1]:
                nx = x + dx
                nt = t + 1
                ny = nt

                if 0 <= nx < 2 * n + 1 and 0 <= nt <= n:
                    if ny not in ships[nt]:
                        new_cost = cost + 1
                        if new_cost < dp[nt][nx]:
                            dp[nt][nx] = new_cost
                            heapq.heappush(pq, (new_cost, nt, nx))

        return "impossible"

    def reconstruct_path(dp, n, x):
        path = []
        t = n
        while t > 0:
            if x > 0 and dp[t][x] == dp[t-1][x-1] + 1:
                path.append('+')
                x -= 1
            elif x < 2 * n and dp[t][x] == dp[t-1][x+1] + 1:
                path.append('-')
                x += 1
            else:
                path.append('0')
            t -= 1
        path.reverse()
        return ''.join(path)

    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    index += 1
    m = int(data[index])
    index += 1

    ships = [set() for _ in range(n + 1)]
    for _ in range(m):
        x1 = int(data[index])
        index += 1
        x2 = int(data[index])
        index += 1
        y = int(data[index])
        index += 1
        for x in range(x1, x2 + 1):
            ships[y].add(x + n)

    result = dijkstra(n, m, ships)
    print(result)

if __name__ == "__main__":
    main()
